    assert.equal(git(f.work, ['merge-base', '--is-ancestor', moved, 'HEAD']) !== null, true, 'the branch now contains the moved base');
    assert.equal(bindsDiff(f.work, 'origin/main'), true);
    f.pull.head = f.head();
