  // review. A line inside a hunk's context changes that hunk: the merged head is reviewed.
  const long = Array.from({length: 20}, (_, index) => `const line${index} = ${index};`).join('\n') + '\n';
  for (const [line, reviewed] of [[18, false], [3, true]]) {
