    // GitHub updates the branch with a plain merge that leaves the diff unchanged: still up to date, as CI will judge it.
    git(f.work, ['fetch', '-q', 'origin', 'main']); git(f.work, ['merge', '-q', '--no-ff', '--no-edit', 'origin/main']);
